package vn.covie.cart.model;
import jakarta.persistence.*; import java.time.Instant; import java.util.UUID;
@Entity @Table(name="carts") public class CartEntity{@Id private UUID id;@Column(name="user_id",nullable=false)private UUID userId;@Column(name="merchant_location_id",nullable=false)private UUID merchantLocationId;@Enumerated(EnumType.STRING)@Column(name="cart_type",nullable=false)private CartType cartType;@Enumerated(EnumType.STRING)@Column(name="cart_status",nullable=false)private CartStatus cartStatus;@Column(name="created_at",nullable=false)private Instant createdAt;@Column(name="updated_at",nullable=false)private Instant updatedAt;@Version private long version;protected CartEntity(){}public static CartEntity active(UUID id,UUID user,UUID location,CartType type,Instant now){CartEntity c=new CartEntity();c.id=id;c.userId=user;c.merchantLocationId=location;c.cartType=type;c.cartStatus=CartStatus.ACTIVE;c.createdAt=now;c.updatedAt=now;return c;}public void touch(Instant now){updatedAt=now;}public void abandon(Instant now){cartStatus=CartStatus.ABANDONED;updatedAt=now;}public UUID getId(){return id;}public UUID getUserId(){return userId;}public UUID getMerchantLocationId(){return merchantLocationId;}public CartType getCartType(){return cartType;}public CartStatus getCartStatus(){return cartStatus;}public long getVersion(){return version;}}
